using UnityEngine;
namespace LWS.TruckDodgeball {
public sealed class DodgeBall:MonoBehaviour {
 public DodgeMatch match;public Rigidbody body;public SphereCollider shape;public Renderer shell;public TrailRenderer trail;public int index;public int Team{get;private set;}=-1;public int Flight{get;private set;}public int Striker{get;private set;}=-1;public float GraceUntil{get;private set;}public int Strikes{get;private set;}public double LastStrikeStep{get;private set;}=double.NegativeInfinity;
 MaterialPropertyBlock color;Vector3 incoming,previous;float stepTime;
 void Awake(){color=new MaterialPropertyBlock();}
 public void ResetBall(Vector3 p){gameObject.SetActive(true);body.isKinematic=false;body.detectCollisions=true;body.position=p;body.rotation=Quaternion.identity;transform.SetPositionAndRotation(p,Quaternion.identity);body.linearVelocity=body.angularVelocity=Vector3.zero;Strikes=0;LastStrikeStep=double.NegativeInfinity;Neutral();trail.Clear();}
 public void Neutral(){Team=-1;Striker=-1;GraceUntil=0;Flight++;Paint();}
 void Paint(){if(color==null)color=new MaterialPropertyBlock();var c=Team<0?new Color(.92f,.91f,.76f):Team==0?new Color(.1f,.6f,1):new Color(1,.3f,.05f);color.SetColor("_BaseColor",c);color.SetColor("_Color",c);shell.SetPropertyBlock(color);trail.startColor=c;trail.endColor=new Color(c.r,c.g,c.b,0);}
 public bool Strike(int slot,Vector3 facing,float time){if(!match.Live||match.Stage!=DodgeStage.Playing||!match.rules.alive[slot]||LastStrikeStep==Time.fixedTimeAsDouble)return false;LastStrikeStep=Time.fixedTimeAsDouble;Team=match.rules.Team(slot);Striker=slot;GraceUntil=time+.28f;Flight++;Strikes++;var flat=Vector3.ProjectOnPlane(facing,Vector3.up).normalized;if(flat.sqrMagnitude<.1f)flat=Vector3.forward;var desired=flat*(match.Clock>=match.suddenDeath?match.suddenStrikeSpeed:match.strikeSpeed)+Vector3.up*match.strikeLift;body.AddForce(desired-body.linearVelocity,ForceMode.VelocityChange);Paint();match.StrikeCount++;match.feedback.Play(2,0,true);match.Pulse(slot,.25f,.1f);return true;}
 public void Stamp(){incoming=body.linearVelocity;previous=body.position;stepTime=Time.fixedTime;}
 void OnCollisionEnter(Collision collision){if(!match.Live||match.Stage!=DodgeStage.Playing)return;var fighter=collision.rigidbody!=null?collision.rigidbody.GetComponent<DodgeFighter>():null;bool ground=collision.collider.GetComponentInParent<DodgeGround>()!=null;if(fighter==null&&!ground)return;float first=stepTime+Time.fixedDeltaTime;for(int i=0;i<collision.contactCount;i++){var contact=collision.GetContact(i);var velocity=incoming-(fighter!=null?fighter.Incoming:Vector3.zero);float speed=Mathf.Max(0,-Vector3.Dot(velocity,contact.normal));float distance=Mathf.Max(0,Vector3.Dot(previous-contact.point,contact.normal)-shape.radius*Mathf.Max(Mathf.Abs(transform.lossyScale.x),Mathf.Max(Mathf.Abs(transform.lossyScale.y),Mathf.Abs(transform.lossyScale.z))));float time=stepTime+Mathf.Clamp(speed>.01f?distance/speed:0,0,Time.fixedDeltaTime);first=Mathf.Min(first,time);}match.Contact(index,fighter!=null?fighter.slot:-1,ground,first,Flight);}
 public void Freeze(){body.isKinematic=true;trail.emitting=false;}public void Wake(){body.isKinematic=false;trail.emitting=true;}
}
}
